import pandas as pd

def clean(df):
    df = df.copy()
    cat_map = {
        'electronics': 'Electronics',
        'electornics': 'Electronics',
        'accessories': 'Accessories',
        'accesories': 'Accessories',
        'furniture': 'Furniture',
        'office supplies': 'Office Supplies',
        'office suplies': 'Office Supplies'
    }
    def norm_cat(x):
        if pd.isna(x):
            return x
        s = str(x).strip()
        key = ' '.join(s.lower().split())
        return cat_map.get(key, s)
    df['Category'] = df['Category'].map(norm_cat)
    def norm_region(x):
        if pd.isna(x):
            return x
        return str(x).strip().title()
    df['Region'] = df['Region'].map(norm_region)
    df['Date'] = pd.to_datetime(df['Date'], errors='coerce')
    for c in ['Quantity', 'Price', 'Revenue']:
        if c in df.columns:
            df[c] = pd.to_numeric(df[c], errors='coerce')
    if 'Quantity' in df.columns and 'Price' in df.columns:
        df['Revenue'] = df['Quantity'] * df['Price']
    return df

def answer(df):
    d = clean(df)
    d = d.dropna(subset=['Category'])
    out = d.groupby('Category', dropna=True)['Revenue'].sum()
    return {str(k): float(v) for k, v in out.items()}
